program = '''from collections import defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    by_color = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                by_color[grid[r][c]].append((r, c))

    objects = {}
    for color, cells in by_color.items():
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        mask = [[grid[r][c] == color for c in range(c0, c1 + 1)]
                for r in range(r0, r1 + 1)]
        objects[color] = (r0, c0, mask)

    # The source is the framed object whose interior contains the pattern.
    sources = []
    for color, (r0, c0, mask) in objects.items():
        if any(mask[r][c] for r in range(1, len(mask)-1)
               for c in range(1, len(mask[0])-1)):
            sources.append(color)
    if not sources:
        return out
    source = sources[0]
    sr0, sc0, pattern = objects[source]
    sh, sw = len(pattern), len(pattern[0])

    for color, (r0, c0, mask) in objects.items():
        if color == source:
            continue
        # Clear the old frame/object, then fill matching-sized frames with
        # the source's bitmap in the target color.
        for r, row in enumerate(mask):
            for c, present in enumerate(row):
                if present:
                    out[r0+r][c0+c] = 0
        if len(mask) == sh and len(mask[0]) == sw:
            for r in range(sh):
                for c in range(sw):
                    if pattern[r][c]:
                        out[r0+r][c0+c] = color
    return out
'''
